	/** 
	 * jumpstart the process by instantiating2 Procedure
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		procedureId = ProcedureService.getProcedureInstance()
		.createProcedure( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ProcedureService.getProcedureInstance()
				.createProcedure( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.procedureSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Procedure : " + successValue.getProcedureId());
							  if (successValue.getProcedureId().equals(procedureId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfProcedureList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Procedure test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on procedure consumed")
					);
			subscriber.procedureSubscribe( procedureId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Procedure : " + successValue.getProcedureId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfProcedureList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on procedure for procedureId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Procedure. 
	 */
	protected Procedure read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Procedure" );

		Procedure entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Procedure with primary key" );
		msg.append( procedureId );
		
		ProcedureFetchOneSummary fetchOneSummary = new ProcedureFetchOneSummary( procedureId );

		try {
			entity = ProcedureService.getProcedureInstance().getProcedure( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Procedure " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Procedure.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Procedure." );

		StringBuilder msg = new StringBuilder( "Failed to update a Procedure : " );        
		Procedure entity = read();
		UpdateProcedureCommand command = generateUpdateCommand();
		command.setProcedureId(entity.getProcedureId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Procedure." );

			// for use later on...
			procedureId = entity.getProcedureId();

			ProcedureService proxy = ProcedureService.getProcedureInstance();  

			proxy.updateProcedure( command ).get();

			LOGGER.info( "-- Successfully saved Procedure - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + procedureId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Procedure.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Procedure." );

		Procedure entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Procedure with id " + procedureId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Procedure with id " + procedureId );

			throw e;
		}

		try{
			ProcedureService.getProcedureInstance().delete( new DeleteProcedureCommand( entity.getProcedureId() ) ).get();
			LOGGER.info( "-- Successfully deleted Procedure with id " + procedureId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Procedure with id " + procedureId );

			throw e;
		}
	}

	/**
	 * get all Procedures.
	 */
	protected List<Procedure> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Procedures:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Procedure : " );        
		List<Procedure> collection  = new ArrayList<>();

		try {
			// call the static get method on the ProcedureService
			collection = ProcedureService.getProcedureInstance().getAllProcedure();
			assertNotNull( collection, "An Empty collection of Procedure was incorrectly returned.");
			
			// Now print out the values
			Procedure entity = null;            
			Iterator<Procedure> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getProcedureId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

